import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createCatalog } from './catalog.ts';
test('catalog invariants', () => { const catalog = createCatalog(); catalog.add('A', 2); assert.equal(catalog.stock('A'), 2); assert.throws(() => catalog.add('A', 3)); assert.throws(() => catalog.add('B', -1)); assert.throws(() => catalog.add('B', 0.5)); });

export function createCatalog() {
  const products = new Map<string, number>();
  return { add(sku: string, stock: number) {
    if (!sku || !Number.isInteger(stock) || stock < 0 || products.has(sku)) throw new Error('Invalid product');
    products.set(sku, stock);
  }, stock(sku: string) { return products.get(sku); } };
}

